-- Homely Taste — run this once in the SQL editor of the new backend project.
-- Creates the menu + orders tables, access rules, and loads the full price list.

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text not null,
  image_url text not null,
  price numeric not null,
  currency text not null default 'LSL',
  category text not null default 'Bakery',
  is_bestseller boolean not null default false,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  size_options jsonb not null default '[]'::jsonb
);

grant select on public.products to anon, authenticated;
grant all on public.products to service_role;
alter table public.products enable row level security;
drop policy if exists "Anyone can view products" on public.products;
create policy "Anyone can view products" on public.products for select to anon, authenticated using (true);

create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  reference text not null,
  customer_name text not null,
  phone text not null,
  occasion text,
  needed_date date not null,
  notes text,
  items jsonb not null default '[]'::jsonb,
  total numeric not null default 0,
  currency text not null default 'LSL',
  status text not null default 'pending',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

grant select, insert, update on public.orders to authenticated;
grant insert on public.orders to anon;
grant all on public.orders to service_role;
alter table public.orders enable row level security;

drop policy if exists "Anyone can submit an order" on public.orders;
create policy "Anyone can submit an order" on public.orders for insert to anon, authenticated with check (true);

drop policy if exists "Owner can view orders" on public.orders;
create policy "Owner can view orders" on public.orders for select to authenticated
  using (lower(auth.jwt() ->> 'email') = 'homelytaste.25@gmail.com');

drop policy if exists "Owner can update orders" on public.orders;
create policy "Owner can update orders" on public.orders for update to authenticated
  using (lower(auth.jwt() ->> 'email') = 'homelytaste.25@gmail.com')
  with check (lower(auth.jwt() ->> 'email') = 'homelytaste.25@gmail.com');

create or replace function public.update_updated_at_column()
returns trigger language plpgsql set search_path = public as $$
begin new.updated_at = now(); return new; end; $$;

drop trigger if exists update_orders_updated_at on public.orders;
create trigger update_orders_updated_at before update on public.orders
  for each row execute function public.update_updated_at_column();

